// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");
        uint256 balanceBefore = c.balances(actor);
        vm.prank(actor);
        try c.withdraw() { } catch { }
        uint256 balanceAfter = c.balances(actor);
        assertTrue(balanceAfter == 0);
    }
}
